                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            comps.append((color, cells))
    return comps


def _orientations(shape):
    forms = set()
    points = list(shape)
    for reflect in (1, -1):
        for turns in range(4):
            pts = []
            for y, x in points:
                x *= reflect
                for _ in range(turns):
                    y, x = x, -y
                pts.append((y, x))
            my, mx = min(y for y, x in pts), min(x for y, x in pts)
            forms.add(frozenset((y - my, x - mx) for y, x in pts))
    return forms


def _fits(small, large):
    # Is the small object's complete shape present as a subset of the larger
    # object, allowing rotations and reflections?
    large_set = set(large)
    for form in _orientations(small):
        mh = max(y for y, x in form) + 1
        mw = max(x for y, x in form) + 1
        for oy in range(min(y for y, x in large_set), max(y for y, x in large_set) - mh + 2):
